import { useEffect,useState } from 'react'
export default function Estabelecimentos(){const [items,setItems]=useState([]),[nome,setNome]=useState(''),[slug,setSlug]=useState('');const carregar=()=>fetch('/api/estabelecimentos').then(r=>r.json()).then(setItems);useEffect(()=>{carregar()},[]);const criar=async e=>{e.preventDefault();const r=await fetch('/api/estabelecimentos',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({nome,slug})});if(!r.ok){const d=await r.json().catch(()=>({}));alert(d.erro||'Erro');return}setNome('');setSlug('');carregar()};const selecionar=id=>{localStorage.setItem('estabelecimentoId',id);window.location.reload()};return <div><div className="section-head"><div><h2>Estabelecimentos</h2><div className="muted">Base multi-estabelecimento do produto</div></div></div><form className="card" onSubmit={criar}><div className="form-grid"><div className="field"><label>Nome</label><input value={nome} onChange={e=>setNome(e.target.value)} required/></div><div className="field"><label>Slug</label><input value={slug} onChange={e=>setSlug(e.target.value)} placeholder="minha-loja" required/></div></div><button className="btn btn-primary" style={{marginTop:12}}>Criar estabelecimento</button></form><div style={{display:'grid',gap:10,marginTop:14}}>{items.map(i=><div className="card" key={i.id} style={{display:'flex',justifyContent:'space-between',alignItems:'center'}}><div><strong>{i.nome}</strong><div className="muted">/{i.slug}</div></div><button className="btn btn-ghost" onClick={()=>selecionar(i.id)}>Usar este</button></div>)}</div></div>}
